  'left_ear': ['Sol kulak', 'Left ear', 'Linkes Ohr', 'Oído izquierdo', 'Oreille gauche', 'الأذن اليسرى', 'گوش چپ', 'אוזן שמאל', 'بایاں کان', 'Левое ухо', 'Ліве вухо', 'Lewe ucho', 'Levé ucho', 'Urechea stângă', 'Bal fül', 'Αριστερό αυτί', 'Orecchio sinistro', 'Ouvido esquerdo', 'Linkeroor', 'Vänster öra', 'Venstre øre', 'Venstre øre', 'Vasen korva', '左耳', '왼쪽 귀', '左耳', 'बायां कान', 'বাঁ কান', 'Telinga kiri', 'Telinga kiri', 'หูซ้าย', 'Tai trái', 'Kaliwang tainga'],
